//! ↩️ Changed frame inverses preserve original absolute scalar values and original identity owners.
use crate::LayoutMutation;
use semio_s_artifact_layout_layout_model::{Frame,snapshot::LayoutSnapshot};
use semio_framework_os_kernel::{RetainedFieldPreparation,RetainedMutationCloseContext};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use semio_framework_value_factory::vector::FactoryVectorRetirement;
use super::batch_plan::FrameSelectionPlan;
use std::mem::{size_of,ManuallyDrop};
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"batch inverse original custody is invalid")}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<LayoutMutation>()*4+512,depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=fixed().copy_bytes;d.depth+=1;d}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-fixed().copy_bytes,maximum_depth:g.maximum_depth-1,..g}}
fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_bytes+=fixed().copy_bytes;p.copied_items=p.copied_items.max(1);p}
fn refused(e:ValueError)->ValueError{let p=receipt(e.retained_progress());e.with_retained_progress(p)}
fn factor(m:&LayoutMutation)->Result<usize,ValueError>{match m{LayoutMutation::DragFrames(_)=>Ok(1),LayoutMutation::RotateFrames(_)|LayoutMutation::ScaleFrames(_)=>Ok(2),_=>Err(fault())}}
fn page<'a>(b:RetainedCloneRef<'a,LayoutSnapshot>,at:usize)->RetainedCloneRef<'a,String>{b.project(9,|b|&b.pages).project(at,move|rows|&rows[at]).project(0,|p|&p.id)}
fn id<'a>(b:RetainedCloneRef<'a,LayoutSnapshot>,at:usize,frame:usize)->RetainedCloneRef<'a,String>{b.project(9,|b|&b.pages).project(at,move|rows|&rows[at]).project(2,|p|&p.frames).project(frame,move|rows|&rows[frame]).project(0,|f|match f{Frame::Rect{id,..}|Frame::Text{id,..}|Frame::Image{id,..}=>id})}
/// 🧳 Every partial event owns its transferred String before the next original field is visited.
pub struct BatchInverse{page:RetainedFieldPreparation<String>,id:RetainedFieldPreparation<String>,rows:ManuallyDrop<Option<Vec<LayoutMutation>>>,retirement:Option<FactoryVectorRetirement<LayoutMutation>>,phase:u8,index:usize,closing:bool}
impl Default for BatchInverse{fn default()->Self{Self{page:Default::default(),id:Default::default(),rows:ManuallyDrop::new(None),retirement:None,phase:0,index:0,closing:false}}}
impl BatchInverse{
 pub fn demand(&self,plan:&FrameSelectionPlan,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{plan.verify(m,b)?;if self.closing||!plan.ready()||plan.failure.is_some(){return Err(fault())}let n=factor(m.get())?;let frame=plan.changed().get(self.index/n).map(|row|row.frame);Ok(match self.phase{0=>RetirementDemand{capacity_bytes:plan.changed().len().checked_mul(n).and_then(|n|n.checked_mul(size_of::<LayoutMutation>())).ok_or_else(fault)?,..fixed()},1=>if frame.is_none()||self.page.value().is_some(){fixed()}else{nested(self.page.demand(page(b,plan.page),body.min(256))?)},2=>if self.id.value().is_some(){fixed()}else{nested(self.id.demand(id(b,plan.page,frame.ok_or_else(fault)?),body.min(256))?)},3=>nested(self.page.exchange_demand()?),4=>nested(self.id.exchange_demand()?),5=>nested(self.page.close_demand(body.min(256))?),6=>nested(self.id.close_demand(body.min(256))?),7|8=>fixed(),_=>return Err(fault())})}
 pub fn advance(&mut self,plan:&FrameSelectionPlan,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(plan,m,b,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};let n=factor(m.get())?;match self.phase{
 0=>{self.phase=254;*self.rows=Some(Vec::new());let rows=self.rows.as_mut().unwrap();let reserved=rows.try_reserve_exact(plan.changed().len()*n);p.retained_capacity_bytes=rows.capacity()*size_of::<LayoutMutation>();if reserved.is_err()||p.retained_capacity_bytes>g.maximum_capacity_bytes{return Err(fault().with_retained_progress(p))}self.phase=1},
 1=>if self.index==plan.changed().len()*n{self.phase=8}else if self.page.value().is_some(){self.phase=2}else{p=receipt(self.page.advance(page(b,plan.page),body.min(256),child(g)).map_err(refused)?.progress())},
 2=>if self.id.value().is_some(){self.phase=3}else{let at=plan.changed()[self.index/n].frame;p=receipt(self.id.advance(id(b,plan.page,at),body.min(256),child(g)).map_err(refused)?.progress())},
 3=>{let(value,paid)=self.page.take(child(g)).map_err(refused)?;p=receipt(paid);let page_id=value.ok_or_else(fault)?;let bounds=b.get().pages[plan.page].frames[plan.changed()[self.index/n].frame].bounds();let row=if self.index%n==0{LayoutMutation::MoveFrame(crate::move_frame::MoveFrame{page_id,frame_id:String::new(),new_x:bounds.x,new_y:bounds.y})}else if matches!(m.get(),LayoutMutation::RotateFrames(_)){LayoutMutation::RotateFrame(crate::rotate_frame::RotateFrame{page_id,frame_id:String::new(),new_rotation:bounds.rotation})}else{LayoutMutation::ResizeFrame(crate::resize_frame::ResizeFrame{page_id,frame_id:String::new(),new_width:bounds.width,new_height:bounds.height})};self.rows.as_mut().ok_or_else(fault)?.push(row);self.phase=4},
 4=>{let(value,paid)=self.id.take(child(g)).map_err(refused)?;p=receipt(paid);let id=value.ok_or_else(fault)?;match self.rows.as_mut().ok_or_else(fault)?.last_mut().ok_or_else(fault)?{LayoutMutation::MoveFrame(p)=>p.frame_id=id,LayoutMutation::RotateFrame(p)=>p.frame_id=id,LayoutMutation::ResizeFrame(p)=>p.frame_id=id,_=>return Err(fault())}self.page.begin_close();self.id.begin_close();self.phase=5},
 5=>{p=receipt(self.page.close_step(child(g)).map_err(refused)?.progress());if self.page.terminal_is_empty(){self.phase=6}},6=>{p=receipt(self.id.close_step(child(g)).map_err(refused)?.progress());if self.id.terminal_is_empty(){self.phase=7}},7=>{self.page=Default::default();self.id=Default::default();self.index+=1;self.phase=1},8=>{},_=>return Err(fault())}Ok(if self.phase==8{RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn take_demand(&self)->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Option<Vec<LayoutMutation>>>()*2,depth:1,..Default::default()}}
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<(Option<Vec<LayoutMutation>>,RetainedCloneProgress),ValueError>{if self.phase!=8||self.closing{return Err(fault())}let d=self.take_demand();if !retained_clone_grant_admits(g,d){return Ok((None,Default::default()))}self.phase=9;Ok((self.rows.take(),RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn begin_close(&mut self){self.closing=true;self.page.begin_close();self.id.begin_close()}
 pub fn close_demand(&self,c:RetainedMutationCloseContext<'_,LayoutMutation>,body:usize)->Result<RetirementDemand,ValueError>{if !self.page.terminal_is_empty(){return self.page.close_demand(body)}if !self.id.terminal_is_empty(){return self.id.close_demand(body)}if let Some(owner)=self.retirement.as_ref(){return if owner.terminal_is_empty(){Ok(fixed())}else{owner.demands(c.mutations,body)}}if self.rows.is_some(){return Ok(FactoryVectorRetirement::<LayoutMutation>::constructor_demand())}Ok(fixed())}
 pub fn close_step(&mut self,c:RetainedMutationCloseContext<'_,LayoutMutation>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{if !self.closing{return Err(fault())}let d=self.close_demand(c,g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.page.terminal_is_empty(){return self.page.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.id.terminal_is_empty(){return self.id.close_step(g).map(|s|RetainedCloneStep::Progress(s.progress()))}if let Some(owner)=self.retirement.as_mut(){if owner.terminal_is_empty(){self.retirement=None;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}return owner.close_step(c.mutations,g).map(|s|RetainedCloneStep::Progress(s.progress()))}if let Some(rows)=self.rows.take(){match FactoryVectorRetirement::admit(rows,g){Ok((owner,p))=>{self.retirement=Some(owner);return Ok(RetainedCloneStep::Progress(p))},Err((error,rows))=>{*self.rows=Some(rows);return Err(error)}}}Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.page.terminal_is_empty()&&self.id.terminal_is_empty()&&self.rows.is_none()&&self.retirement.is_none()}
}
impl Drop for BatchInverse{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"batch inverse needs original funded cleanup")}}
